%% ── Derived: throttle required to maintain hover ─────────────────────────────
% throttle_req = HOVER_THROTTLE_FRAC * (V_full / V_term)
% At full charge: 52% throttle gives hover (from sim parameters)
hover_thr   = 52.0;              % %  — baseline at 100% SOC
v_full      = 4.122;             % V  — terminal voltage at 100% SOC
thr_req_pct = hover_thr .* (v_full ./ v_ds);

%% ── Annotation values ────────────────────────────────────────────────────────
idx_50 = find(soc_ds <= 50.5, 1, 'first');
soc_50 = soc_ds(idx_50);   thr_50 = thr_req_pct(idx_50);
soc_5  = soc_ds(end);      thr_5  = thr_req_pct(end);

%% ── Colours ──────────────────────────────────────────────────────────────────
cV      = [0.12 0.35 0.80];   % blue   — terminal voltage
cThr    = [0.85 0.18 0.18];   % red    — thrust %
cOrange = [1.00 0.55 0.00];   % orange — required throttle / fill

%% ── Figure 1: dual y-axis — voltage + thrust ─────────────────────────────────
figure('Name','A6 Fig1 — Voltage & Thrust','Position',[60 60 1200 500]);
ax1 = axes('Position',[0.10 0.15 0.80 0.72]);

yyaxis(ax1, 'left');
plot(ax1, soc_ds, v_ds, '-', 'Color',cV, 'LineWidth',2.4, ...
     'DisplayName','Terminal voltage V_{term}');
ylabel(ax1, 'Voltage  (V)', 'FontSize',25);
ax1.YAxis(1).Color = cV;
ylim(ax1, [min(v_ds)-0.1  max(v_ds)+0.1]);

yyaxis(ax1, 'right');
plot(ax1, soc_ds, thr_ds, '--', 'Color',cThr, 'LineWidth',2.0, ...
     'DisplayName','Thrust at const throttle (%)');
ylabel(ax1, 'Thrust at const throttle  (%)', 'FontSize',25);
ax1.YAxis(2).Color = cThr;
ylim(ax1, [min(thr_ds)-5  105]);

set(ax1, 'XLim',[5 100], 'XDir','reverse', 'Box','off', ...
         'YGrid','on','XGrid','off','GridAlpha',0.25,'GridLineStyle','--');
xlabel(ax1, 'State of Charge  (%)', 'FontSize',25);
title(ax1, 'EXP-A6: Battery Discharge — Thrust Degradation', 'FontSize',25);
legend(ax1, 'FontSize',17, 'Location','southwest', 'Box','off');

%% ── Figure 2: required throttle to maintain hover ────────────────────────────
axP2  = [0.10 0.15 0.82 0.72];
XLIM2 = [100 5];
YLIM2 = [hover_thr - 2,  thr_5 + 6];

figure('Name','A6 Fig2 — Required Throttle','Position',[100 60 1200 500]);
ax2 = axes('Position', axP2);
hold on;

% Shaded fill — extra throttle needed
x_fill = [soc_ds;          flipud(soc_ds)];
y_fill = [thr_req_pct;     repmat(hover_thr, size(soc_ds))];
patch(ax2, x_fill, y_fill, cOrange, 'FaceAlpha',0.15, 'EdgeColor','none', ...
      'DisplayName','Extra throttle needed (battery deficit)');

% Required throttle curve
plot(ax2, soc_ds, thr_req_pct, '-', 'Color',cOrange, 'LineWidth',2.4, ...
     'DisplayName','Required throttle to maintain hover');

% Baseline
plot(ax2, [100 5], [hover_thr hover_thr], ':', 'Color',[0.50 0.50 0.50], ...
     'LineWidth',1.2, 'DisplayName', ...
     sprintf('Baseline hover throttle at 100%% SOC (%.0f%%)', hover_thr));

% Arrow helper: data coords → normalised figure coords (works for reversed x-axis)
xn = @(x) axP2(1) + axP2(3).*(x - XLIM2(1))./(XLIM2(2)-XLIM2(1));
yn = @(y) axP2(2) + axP2(4).*(y - YLIM2(1))./(YLIM2(2)-YLIM2(1));

% Annotation: 50% SOC
txt50 = [soc_50+5,  thr_50+2.5];
text(ax2, txt50(1), txt50(2), sprintf('%.1f%% throttle\nat 50%% SOC', thr_50), ...
     'FontSize',17, 'Color',cOrange, 'HorizontalAlignment','left');
annotation('arrow', [xn(txt50(1)) xn(soc_50)], [yn(txt50(2)) yn(thr_50)], ...
           'Color',cOrange, 'LineWidth',1.2, 'HeadLength',8, 'HeadWidth',6);

% Annotation: 5% SOC
txt5 = [soc_5+12,  thr_5+2.5];
text(ax2, txt5(1), txt5(2), sprintf('%.1f%% throttle\nat 5%% SOC', thr_5), ...
     'FontSize',17, 'Color',cOrange, 'HorizontalAlignment','left');
annotation('arrow', [xn(txt5(1)) xn(soc_5)], [yn(txt5(2)) yn(thr_5)], ...
           'Color',cOrange, 'LineWidth',1.2, 'HeadLength',8, 'HeadWidth',6);

set(ax2, 'XLim',[5 100], 'XDir','reverse', 'YLim',YLIM2, 'Box','off', ...
         'YGrid','on','XGrid','off','GridAlpha',0.25,'GridLineStyle','--');
xlabel(ax2, 'State of Charge  (%)', 'FontSize',25);
ylabel(ax2, 'Required throttle  (%)', 'FontSize',25);
title(ax2, 'Throttle Required to Maintain Hover vs Battery SOC', 'FontSize',25);
legend(ax2, 'FontSize',17, 'Location','northwest', 'Box','off');
hold off;
